<?php $pageTitle='Validasi Duplikasi'; require_once 'config/database.php'; require_once 'config/auth.php'; require_role(['Petugas Registrasi','Petugas Rekam Medis','Administrator SIMRS']);$msg='';if(isset($_POST['flag'])){$id=(int)$_POST['id'];$pdo->prepare('UPDATE patients SET duplicate_flag=1 WHERE id=?')->execute([$id]);audit($pdo,'FLAG_DUPLICATE','patients',$id,'Pasien ditandai untuk validasi identitas');$msg='Pasien ditandai untuk validasi identitas.';}if(isset($_POST['clear'])){$id=(int)$_POST['id'];$pdo->prepare('UPDATE patients SET duplicate_flag=0 WHERE id=?')->execute([$id]);audit($pdo,'CLEAR_DUPLICATE','patients',$id,'Hasil validasi tidak menunjukkan duplikasi');$msg='Penanda validasi telah diselesaikan.';}$cand=$pdo->query("SELECT * FROM patients WHERE duplicate_flag=1 ORDER BY id DESC")->fetchAll();$all=$pdo->query("SELECT id,medical_record_no,name,nik,dob FROM patients ORDER BY name")->fetchAll();include 'partials/header.php'; ?>
<?php if($msg): ?><div class="alert">✓ <?=e($msg)?></div><?php endif; ?><div class="grid"><div class="s-5"><div class="card"><div class="card-title"><div><h2>Validasi identitas</h2><p>Gunakan saat ditemukan indikasi pasien memiliki data ganda.</p></div></div><form method="post"><label>Pasien</label><select name="id" required><option value="">Pilih pasien</option><?php foreach($all as $p): ?><option value="<?=$p['id']?>"><?=e($p['name'])?> • <?=e($p['medical_record_no'])?></option><?php endforeach; ?></select><button class="btn" name="flag" style="width:100%;margin-top:14px">Tandai untuk Review</button></form></div><div class="card mt"><div class="eyebrow">PRINSIP ADMINISTRASI</div><h3 style="margin:5px 0">Satu pasien, satu identitas</h3><div class="hint">Sebelum membuat nomor RM baru, pastikan pasien belum memiliki identitas aktif pada sistem.</div></div></div><div class="s-7"><div class="card"><div class="card-title"><div><h2>Daftar untuk ditinjau</h2><p>Pasien yang memerlukan pemeriksaan lanjutan oleh petugas.</p></div><span class="badge red"><?=count($cand)?> perlu review</span></div><div class="table-wrap"><table><tr><th>Pasien</th><th>No. RM</th><th>NIK</th><th>Tgl. Lahir</th><th>Aksi</th></tr><?php foreach($cand as $p): ?><tr><td><b><?=e($p['name'])?></b></td><td><?=e($p['medical_record_no'])?></td><td><?=e($p['nik'])?></td><td><?=e(date('d/m/Y',strtotime($p['dob'])))?></td><td><form method="post"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn secondary sm" name="clear">Tandai Selesai</button></form></td></tr><?php endforeach; ?></table><?php if(!$cand): ?><div class="empty">Tidak ada pasien yang sedang menunggu validasi.</div><?php endif; ?></div></div></div></div>
<?php include 'partials/footer.php'; ?>
